    <script>
        // Configuración de Toastr
        toastr.options = {
            closeButton: true,
            progressBar: true,
            positionClass: 'toast-bottom-right',
            timeOut: 3000
        };

        // Variables globales
        let allTasks = [];
        let currentFilter = 'pending';
        let currentTask = null;
        let selectedFiles = [];

        // Cargar tareas al iniciar
        document.addEventListener('DOMContentLoaded', function() {
            loadTasks();
            setupDragAndDrop();
        });

        /**
         * Carga las tareas del usuario
         */
        async function loadTasks() {
            showLoading('Cargando tareas...');

            try {
                const response = await fetch('<?php echo url_for("bpmn/tasksMy") ?>?status=' + currentFilter);
                const data = await response.json();

                if (data.success) {
                    allTasks = data.tasks;
                    renderTasksList(allTasks);
                    updateTaskCounts();
                } else {
                    throw new Error(data.error || 'Error al cargar tareas');
                }
            } catch (error) {
                toastr.error('Error: ' + error.message);
            } finally {
                hideLoading();
            }
        }

        /**
         * Renderiza la lista de tareas
         */
        function renderTasksList(tasks) {
            const container = document.getElementById('tasksList');

            if (tasks.length === 0) {
                container.innerHTML = `
                    <div class="empty-state">
                        <i class="fas fa-inbox"></i>
                        <h3>No hay tareas</h3>
                        <p>No tienes tareas ${currentFilter === 'pending' ? 'pendientes' : ''} asignadas</p>
                    </div>
                `;

                document.getElementById('taskDetailContent').style.display = 'none';
                return;
            }

            container.innerHTML = tasks.map(task => {
                const isOverdue = task.due_date && new Date(task.due_date) < new Date();
                const priorityClass = getPriorityClass(task.priority);
                const priorityLabel = getPriorityLabel(task.priority);

                return `
                    <div class="task-item ${isOverdue ? 'overdue' : ''} ${task.priority >= 7 ? 'high-priority' : ''}" 
                         data-task-id="${task.id}"
                         onclick="selectTask(${task.id})">
                        <div class="task-item-header">
                            <span class="task-item-title">${escapeHtml(task.task_name)}</span>
                            <span class="task-item-priority ${priorityClass}">${priorityLabel}</span>
                        </div>
                        <div class="task-item-process">
                            <i class="fas fa-project-diagram"></i> ${escapeHtml(task.workflow_instance.process_name)}
                        </div>
                        <div class="task-item-meta">
                            <span>
                                <i class="fas fa-hashtag"></i> ${task.workflow_instance.id}
                            </span>
                            <span>
                                <i class="fas fa-calendar"></i> ${formatDate(task.created_at)}
                            </span>
                            ${task.due_date ? `
                                <span class="${isOverdue ? 'overdue-text' : ''}">
                                    <i class="fas fa-clock"></i> 
                                    ${isOverdue ? 'Vencida' : formatDate(task.due_date)}
                                </span>
                            ` : ''}
                        </div>
                    </div>
                `;
            }).join('');
        }

        /**
         * Actualiza los contadores de tareas
         */
        function updateTaskCounts() {
            const pendingCount = allTasks.filter(t => ['pending', 'assigned', 'in_progress'].includes(t.status)).length;

            document.getElementById('pendingCount').textContent = pendingCount;
        }

        /**
         * Selecciona una tarea y muestra su detalle
         */
        async function selectTask(taskId) {
            // Marcar como activa
            document.querySelectorAll('.task-item').forEach(item => {
                item.classList.toggle('active', parseInt(item.dataset.taskId) === taskId);
            });

            showLoading('Cargando tarea...');

            try {
                // Obtener detalle completo de la tarea
                const response = await fetch(`<?php echo url_for("bpmn/taskDetail") ?>?task_id=${taskId}`);
                const data = await response.json();

                if (data.success) {
                    currentTask = data.task;
                    renderTaskDetail(currentTask);
                } else {
                    throw new Error(data.error || 'Error al cargar tarea');
                }
            } catch (error) {
                toastr.error('Error: ' + error.message);
            } finally {
                hideLoading();
            }
        }

        /**
         * Renderiza el detalle de la tarea
         */
        function renderTaskDetail(task) {
            // Mostrar panel de detalle
            document.getElementById('taskDetailEmpty').style.display = 'none';
            document.getElementById('taskDetailContent').style.display = 'flex';

            // Llenar información básica
            document.getElementById('currentTaskId').value = task.id;
            document.getElementById('taskDetailTitle').textContent = task.task_name;
            document.getElementById('taskDetailProcess').textContent = task.workflow_instance.process_name;
            document.getElementById('taskDetailWorkflowId').textContent = task.workflow_instance.id;
            document.getElementById('taskDetailCreated').textContent = formatDateTime(task.created_at);

            if (task.due_date) {
                document.getElementById('taskDetailDueContainer').style.display = 'inline-flex';
                document.getElementById('taskDetailDue').textContent = formatDateTime(task.due_date);
            } else {
                document.getElementById('taskDetailDueContainer').style.display = 'none';
            }

            console.log(task.status);

            // Mostrar variables del workflow
            if (task.workflow_variables && Object.keys(task.workflow_variables).length > 0) {
                document.getElementById('workflowVariablesSection').style.display = 'block';
                renderWorkflowVariables(task.workflow_variables);
            } else {
                document.getElementById('workflowVariablesSection').style.display = 'none';
            }

            // Renderizar formulario dinámico
            renderDynamicForm(task.form_fields || []);

            // Cargar archivos existentes
            if (task.workflow_attachments && task.workflow_attachments.length > 0) {
                document.getElementById('existingFilesSection').style.display = 'block';
                renderExistingFiles(task.workflow_attachments);
            } else {
                document.getElementById('existingFilesSection').style.display = 'none';
            }

            // Limpiar archivos seleccionados
            selectedFiles = [];
            document.getElementById('uploadedFilesList').innerHTML = '';
            document.getElementById('taskComments').value = '';
        }

        /**
         * Renderiza las variables del workflow
         */
        function renderWorkflowVariables(variables) {
            const container = document.getElementById('workflowVariables');
            //console.log(variables);
            // Filtrar variables internas (que empiezan con _)
            const visibleVars = Object.entries(variables).filter(([key]) => !key.startsWith('_'));

            container.innerHTML = visibleVars.map(([key, value]) => `
                <div class="variable-item">
                    <div class="variable-item-label">${escapeHtml(key)}</div>
                    <div class="variable-item-value">${escapeHtml(String(value))}</div>
                </div>
            `).join('');
        }

        /**
         * Renderiza el formulario dinámico basado en la configuración
         */
        function renderDynamicForm(formFields) {
            const container = document.getElementById('dynamicFormFields');
            //console.log(currentTask);
            if (!formFields || formFields.length === 0) {
                container.innerHTML = `
                    <p style="color: #888; font-style: italic;">
                        Esta tarea no requiere información adicional.
                    </p>
                `;
                return;
            }

            container.innerHTML = formFields.map(field => {
                const required = field.required ? '<span class="required">*</span>' : '';
                const requiredAttr = field.required ? 'required' : '';
                const defaultValue = field.defaultValue || '';

                let inputHtml = '';

                switch (field.type) {
                    case 'string':
                        inputHtml = `
                            <input type="text" 
                                   id="field_${field.id}" 
                                   name="fields[${field.id}]"
                                   value="${escapeHtml(defaultValue)}"
                                   placeholder="Ingresa ${field.label.toLowerCase()}"
                                   ${requiredAttr}>
                        `;
                        break;

                    case 'long':
                        inputHtml = `
                            <input type="number" 
                                   id="field_${field.id}" 
                                   name="fields[${field.id}]"
                                   value="${escapeHtml(defaultValue)}"
                                   placeholder="Ingresa valor numérico"
                                   ${requiredAttr}>
                        `;
                        break;

                    case 'boolean':
                        inputHtml = `
                            <div class="form-check">
                                <input type="checkbox" 
                                       id="field_${field.id}" 
                                       name="fields[${field.id}]"
                                       value="true"
                                       ${defaultValue === 'true' || defaultValue === true ? 'checked' : ''}>
                                <label for="field_${field.id}">${field.label}</label>
                            </div>
                        `;
                        break;

                    case 'date':
                        inputHtml = `
                            <input type="date" 
                                   id="field_${field.id}" 
                                   name="fields[${field.id}]"
                                   value="${escapeHtml(defaultValue)}"
                                   ${requiredAttr}>
                        `;
                        break;

                    case 'enum':
                        const options = field.options || [];
                        inputHtml = `
                            <select id="field_${field.id}" 
                                    name="fields[${field.id}]"
                                    ${requiredAttr}>
                                <option value="">Selecciona una opción</option>
                                ${options.map(opt => `
                                    <option value="${escapeHtml(opt.value || opt)}" 
                                            ${defaultValue === (opt.value || opt) ? 'selected' : ''}>
                                        ${escapeHtml(opt.label || opt)}
                                    </option>
                                `).join('')}
                            </select>
                        `;
                        break;

                    case 'textarea':
                        inputHtml = `
                            <textarea id="field_${field.id}" 
                                      name="fields[${field.id}]"
                                      placeholder="Ingresa ${field.label.toLowerCase()}"
                                      ${requiredAttr}>${escapeHtml(defaultValue)}</textarea>
                        `;
                        break;

                    default:
                        inputHtml = `
                            <input type="text" 
                                   id="field_${field.id}" 
                                   name="fields[${field.id}]"
                                   value="${escapeHtml(defaultValue)}"
                                   ${requiredAttr}>
                        `;
                }

                // Para checkbox no mostrar label arriba
                if (field.type === 'boolean') {
                    return `
                        <div class="form-group" data-field-id="${field.id}">
                            ${inputHtml}
                        </div>
                    `;
                }

                return `
                    <div class="form-group" data-field-id="${field.id}">
                        <label for="field_${field.id}">
                            ${escapeHtml(field.label)} ${required}
                        </label>
                        ${inputHtml}
                    </div>
                `;
            }).join('');
        }

        /**
         * Renderiza los archivos existentes del proceso
         */
        function renderExistingFiles(attachments) {
            const container = document.getElementById('existingFilesList');

            container.innerHTML = attachments.map(file => {
                const iconClass = getFileIconClass(file.mime_type);

                return `
                    <div class="attachment-item">
                        <div class="attachment-info">
                            <div class="attachment-icon ${iconClass}">
                                <i class="fas fa-file"></i>
                            </div>
                            <div class="attachment-details">
                                <h4>${escapeHtml(file.original_filename)}</h4>
                                <span>
                                    ${formatFileSize(file.file_size)} • 
                                    Subido por ${escapeHtml(file.uploaded_by_name || 'Sistema')} • 
                                    ${formatDate(file.created_at)}
                                </span>
                            </div>
                        </div>
                        <div class="attachment-actions">
                            <button type="button" class="btn-download" onclick="downloadFile(${file.id})">
                                <i class="fas fa-download"></i> Descargar
                            </button>
                        </div>
                    </div>
                `;
            }).join('');
        }

        /**
         * Configura drag and drop para archivos
         */
        function setupDragAndDrop() {
            const dropArea = document.getElementById('fileUploadArea');

            ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
                dropArea.addEventListener(eventName, preventDefaults, false);
            });

            function preventDefaults(e) {
                e.preventDefault();
                e.stopPropagation();
            }

            ['dragenter', 'dragover'].forEach(eventName => {
                dropArea.addEventListener(eventName, () => dropArea.classList.add('dragover'), false);
            });

            ['dragleave', 'drop'].forEach(eventName => {
                dropArea.addEventListener(eventName, () => dropArea.classList.remove('dragover'), false);
            });

            dropArea.addEventListener('drop', handleDrop, false);
        }

        function handleDrop(e) {
            const dt = e.dataTransfer;
            const files = dt.files;
            handleFiles(files);
        }

        function handleFileSelect(e) {
            const files = e.target.files;
            handleFiles(files);
        }

        function handleFiles(files) {
            Array.from(files).forEach(file => {
                // Validar tamaño (10MB)
                if (file.size > 10 * 1024 * 1024) {
                    toastr.warning(`El archivo ${file.name} excede el límite de 10MB`);
                    return;
                }

                // Evitar duplicados
                if (selectedFiles.some(f => f.name === file.name)) {
                    toastr.warning(`El archivo ${file.name} ya fue agregado`);
                    return;
                }

                selectedFiles.push(file);
            });

            renderSelectedFiles();
        }

        function renderSelectedFiles() {
            const container = document.getElementById('uploadedFilesList');

            container.innerHTML = selectedFiles.map((file, index) => `
                <div class="uploaded-file-item">
                    <div class="file-info">
                        <i class="fas fa-file"></i>
                        <span>${escapeHtml(file.name)} (${formatFileSize(file.size)})</span>
                    </div>
                    <button type="button" class="remove-file" onclick="removeSelectedFile(${index})">
                        <i class="fas fa-times"></i>
                    </button>
                </div>
            `).join('');
        }

        function removeSelectedFile(index) {
            selectedFiles.splice(index, 1);
            renderSelectedFiles();
        }

        /**
         * Envía el formulario para completar la tarea
         */
        async function submitTask(event) {
            if (event) event.preventDefault();

            if (!currentTask || !['pending', 'in_progress', 'assigned'].includes(currentTask.status)) {
                toastr.warning('No hay tarea seleccionada o la tarea no se encuentra en estado pendiente, en progreso o asignada');
                return;
            }

            // Validar campos requeridos
            const form = document.getElementById('taskForm');
            if (!form.checkValidity()) {
                form.reportValidity();
                return;
            }

            showLoading('Completando tarea...');

            try {
                const formData = new FormData();
                formData.append('task_id', currentTask.id);
                formData.append('comments', document.getElementById('taskComments').value);

                // Recopilar campos del formulario dinámico
                const fields = {};
                document.querySelectorAll('[name^="fields["]').forEach(input => {
                    const fieldName = input.name.match(/fields\[(.+)\]/)[1];
                    if (input.type === 'checkbox') {
                        fields[fieldName] = input.checked;
                    } else {
                        fields[fieldName] = input.value;
                    }
                });
                formData.append('fields', JSON.stringify(fields));

                // Agregar archivos
                selectedFiles.forEach(file => {
                    formData.append('attachments[]', file);
                });

                const response = await fetch('<?php echo url_for("bpmn/taskComplete") ?>', {
                    method: 'POST',
                    body: formData
                });

                const result = await response.json();

                if (result.success) {
                    toastr.success('Tarea completada correctamente');

                    // Recargar lista de tareas
                    await loadTasks();

                    // Limpiar panel de detalle
                    document.getElementById('taskDetailEmpty').style.display = 'flex';
                    document.getElementById('taskDetailContent').style.display = 'none';
                    currentTask = null;
                    selectedFiles = [];

                    // Notificar si hay siguiente tarea
                    if (result.next_task) {
                        toastr.info('Se ha asignado una nueva tarea');
                    }
                } else {
                    throw new Error(result.error || 'Error al completar tarea');
                }
            } catch (error) {
                toastr.error('Error: ' + error.message);
            } finally {
                hideLoading();
            }
        }

        /**
         * Guarda un borrador de la tarea
         */
        async function saveTaskDraft() {
            if (!currentTask || !['pending', 'in_progress', 'assigned'].includes(currentTask.status)) {
                toastr.warning('No hay tarea seleccionada o la tarea no se encuentra en estado pendiente, en progreso o asignada');
                return;
            }

            showLoading('Guardando borrador...');

            try {
                const fields = {};
                document.querySelectorAll('[name^="fields["]').forEach(input => {
                    const fieldName = input.name.match(/fields\[(.+)\]/)[1];
                    if (input.type === 'checkbox') {
                        fields[fieldName] = input.checked;
                    } else {
                        fields[fieldName] = input.value;
                    }
                });

                const response = await fetch('<?php echo url_for("bpmn/taskSaveDraft") ?>', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded',
                    },
                    body: new URLSearchParams({
                        task_id: currentTask.id,
                        fields: JSON.stringify(fields),
                        comments: document.getElementById('taskComments').value
                    })
                });

                const result = await response.json();

                if (result.success) {
                    toastr.success('Borrador guardado');
                } else {
                    throw new Error(result.error || 'Error al guardar borrador');
                }
            } catch (error) {
                toastr.error('Error: ' + error.message);
            } finally {
                hideLoading();
            }
        }

        /**
         * Establece el filtro de tareas
         */
        function setTaskFilter(filter) {
            currentFilter = filter;

            document.querySelectorAll('.filter-tab').forEach(tab => {
                tab.classList.toggle('active', tab.dataset.filter === filter);
            });

            loadTasks();
        }

        /**
         * Filtra tareas por búsqueda
         */
        function filterTasks() {
            const searchTerm = document.getElementById('taskSearch').value.toLowerCase();

            const filtered = allTasks.filter(task => {
                return task.task_name.toLowerCase().includes(searchTerm) ||
                    task.workflow_instance.process_name.toLowerCase().includes(searchTerm);
            });

            renderTasksList(filtered);
        }

        /**
         * Ver historial del workflow
         */
        function viewWorkflowHistory() {
            if (!currentTask) return;
            //window.open(`<?php echo url_for("bpmn/workflowHistory") ?>?workflowinstance_id=${currentTask.workflow_instance.id}`, '_blank');
            javascript: jQuery.OpenModalSIMAD(`<?php echo url_for("bpmn/workflowHistory") ?>?workflowinstance_id=${currentTask.workflow_instance.id}`);
        }

        /**
         * Descarga un archivo
         */
        function downloadFile(fileId) {
            window.open(`<?php echo url_for("bpmn/attachmentDownload") ?>?attachmentId=${fileId}`, '_blank');
        }

        // ============================================================================
        // UTILIDADES
        // ============================================================================

        function showLoading(text = 'Cargando...') {
            document.getElementById('loadingText').textContent = text;
            document.getElementById('loadingOverlay').classList.add('active');
        }

        function hideLoading() {
            document.getElementById('loadingOverlay').classList.remove('active');
        }

        function escapeHtml(text) {
            if (!text) return '';
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        function formatDate(dateString) {
            if (!dateString) return 'N/A';
            const date = new Date(dateString);
            return date.toLocaleDateString('es-ES', {
                year: 'numeric',
                month: 'short',
                day: 'numeric'
            });
        }

        function formatDateTime(dateString) {
            if (!dateString) return 'N/A';
            const date = new Date(dateString);
            return date.toLocaleDateString('es-ES', {
                year: 'numeric',
                month: 'short',
                day: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            });
        }

        function formatFileSize(bytes) {
            if (bytes === 0) return '0 Bytes';
            const k = 1024;
            const sizes = ['Bytes', 'KB', 'MB', 'GB'];
            const i = Math.floor(Math.log(bytes) / Math.log(k));
            return Math.round(bytes / Math.pow(k, i) * 100) / 100 + ' ' + sizes[i];
        }

        function getPriorityClass(priority) {
            if (priority >= 9) return 'priority-urgent';
            if (priority >= 7) return 'priority-high';
            if (priority >= 4) return 'priority-normal';
            return 'priority-low';
        }

        function getPriorityLabel(priority) {
            if (priority >= 9) return 'Urgente';
            if (priority >= 7) return 'Alta';
            if (priority >= 4) return 'Normal';
            return 'Baja';
        }

        function getFileIconClass(mimeType) {
            if (!mimeType) return '';
            if (mimeType.includes('pdf')) return 'pdf';
            if (mimeType.includes('word') || mimeType.includes('document')) return 'doc';
            if (mimeType.includes('excel') || mimeType.includes('spreadsheet')) return 'xls';
            if (mimeType.includes('image')) return 'img';
            return '';
        }
    </script>
</body>

</html>